from book import Chapter
c=Chapter('15')
c.src('R46622',0,start='有一个很明显的例子',end='他在这整个决策最终决定决策结果当中的比重权重就要更高。',replacements=[('有一个很明显的例子，就是往往在这样的组织形式下','在金字塔式的组织形式下，有一个很明显的现象'),('但上层领导其实在这方面对底层的了解远不如上层','但上层领导在这些具体问题上，对基层的了解往往远不如基层'),('尽管就是说制定政策可能需要宏观考虑，但是呢，你必须得这个宏观和微观，底层的实际需求和宏观的顶层的组织之间必须有一个合理的决策权的分配','尽管制定政策需要宏观考虑，但宏观和微观之间，底层的实际需求和整体的组织之间，必须有一个合理的决策权分配'),('也就是说现在的这种金字塔式的决策形式，实际上是极度落后的，不光是决策上会，就是实际上决策正确的概率不高，决策的效率也低，远不如我说的这种动态分配权重','这种金字塔式的决策形式，可能同时损失决策的准确性和效率。我设想的改进方向，就是动态分配权重'),('谁的预测概率，或者说自己的认知能够正确或者有效的概率越高，他在这整个决策最终决定决策结果当中的比重权重就要更高','谁的预测越准确，认知和方案越有效，他的意见在这类决策中的比重就可以更高')])
c.add('''为什么熟悉问题的人常常不能决定，能够决定的人又未必熟悉问题？因为一个人的决策权，往往首先来自他处在什么职位，其次才来自他对眼前这件事情知道多少。职位承担了整合信息和组织行动的功能，但也容易把不同领域、不同情境中的判断权，一并交到同一个人手里。

例如，一家维修组织的负责人可能非常擅长安排预算，却不一定比正在检修设备的工作人员更清楚某个异响意味着什么。反过来，工作人员熟悉这一台设备，也不代表他已经知道整个组织的资金安排。需要解决的事情，并不是在这两个人中选出一个永远正确的人，而是让两种知识在相应的问题上发挥作用。''')
c.heading('决策节点为什么要从固定的人和职位中解放出来')
c.src('R34496',0,start='我的这个动态权重的社会神经网络',end='新生产力的生产关系架构',replacements=[('我的这个','我所设想的'),('(决策网络的节点不再绑定具体的人类精英个体或团体，而是由集体智慧汇聚的算法/规则，也许可以叫做知本主义/智本主义制度？)设想，是一个','，其决策节点不再绑定具体的人类精英个体或团体，而是由集体智慧汇聚成的算法和规则来承担。我希望它成为一个')])
c.add('''这句话需要展开。如果把一位官员换成一个 AI，却仍然只有这个 AI 能看见全部信息、解释规则和宣布结果，那么组织结构并没有发生根本改变。即使它一时非常聪明，其他参与者依然只能等待它的决定。

而在共同的知识网络中，一项能力可以由许多人贡献，一条规则可以留下提出、验证和修改的过程，一个方案可以依赖多个领域中的可靠判断。决策节点因任务而形成，随证据而调整，也能够被新的、更好的构造替换。人仍然作出贡献，仍然承担实际行动，但贡献不必被固定职位包住，规则也不需要成为某个人不可分割的权威。''')
c.src('R34496',72,replacements=[('事实上中国的政府也没有管理一切，决策一切，否则哪里来的市场经济？我设想的制度，不正是解决中国威权体制的缺欠的吗？你提到的面子问题，或者政治责任问题，全都来自于威权体制下，政策规则与具体的领导权威的具体人绑定了。而在一个动态权重的决策系统下，并不存在这种情况。','我所要解决的一个缺欠，就是政策、规则与具体领导者的权威绑定在一起。面子问题、政治责任问题，会使人很难把对某项规则的修正，与对自己地位的否定分开。动态权重的决策系统，要从这种绑定关系中走出来。')])
c.heading('从垃圾邮件的判断，理解一个能够学习的决策过程')
c.src('R49135',0,start='在这个网络中，每个智慧个体',replacements=[('这样就消除了过去人类社会那种静态的权重策略','这种安排所要改变的，是过去人类社会中静态、固化的决策权重'),('而民主制中的一人一票也好，代理人制也好，都需要几年一轮的权重分配','而依赖固定任期选举的代议机制，则把重要的权重调整放在几年一轮的程序中'),('随时动态调整其在该领域意见的权重','根据新的反馈动态调整其在该领域意见的权重')])
c.src('R54886',7,replacements=[('充分博弈的游戏才是整个系统达到最优化的前提','要改善共同决策，就需要让参与者能够更充分地理解情境、交换信息和作出判断'),('充分博弈取决于两个方面。一方面是信息','其中一个重要方面是信息'),('这个任务就可以完成','这个任务就有了不断改进的技术条件')])
c.src('R54886',9,replacements=[('前面所说的机制满足了进行完全博弈的技术底层支持','这样的机制提供了两个相互配合的方向'),('所有信息都透明化','有关共同决定的信息能够被参与者核验'),('拉平了所有人在理性思维能力方面的差距，这样每一个参与博弈的节点都是完全理性人','尽可能拉平参与者在获取知识和进行推理方面的能力差距，让每一个参与博弈的节点都有更好的理性判断条件'),('这不是绝对意义上的','这种对等不是绝对意义上的')])
c.src('R55365',48,start='比如面对确定性问题时',end='我觉得merkle框架为这个复杂政治经济决策算法提供底层的技术支持。',replacements=[('比如面对确定性问题时','面对确定性问题时'),('不再通过传统的威权体制下，由相关专家决定，或者民主体制下，靠选举投票决定，而是通过','我希望能够通过'),('计算各个人类和AI智能个体或组织节点，在历史上对该类问题的解答准确性概率','考察各个人类和 AI 智能个体或组织节点，在历史上对该类问题的判断准确性'),('然后根据这些节点的加权权重','然后综合这些节点的判断及其权重'),('这种动态的智能决策体系，肯定比传统的政治和经济体中的决策体系要科学和准确得多','我希望这种动态的智能决策体系，能够比固定在职位和身份上的决策体系更加科学、准确，也更容易纠错'),('这个算法是我当初被垃圾邮件算法启发而想到的，之前在chatgpt的过往会话中，也提到过','这个设想的一个启发，来自垃圾邮件的判断机制'),('merkle框架','Merkle 框架')])
c.add('''设想我们第一次收到一封陌生邮件。它的标题、发件地址、内容和链接，都可能提供一些线索。但是，某一个词出现了，并不意味着这封邮件一定是垃圾邮件；一个过去可靠的地址，也可能在某一天被盗用。判断需要综合不同线索，并在用户纠正和新邮件到来时继续调整。

我从中得到的启发，是不要把某一个线索永久封为权威，而要让它在反馈中改变自己的作用。把这个思路用于共同决策，也不是给一个人贴上“可靠”或“不可靠”的终身标签。同一个人对机械维修很有经验，对农作物病害可能并不了解；同一个方案在一种环境下有效，换了条件可能就失效。权重因此应该附着在具体领域、具体问题及其适用条件上。

再拿维修举例。三个人分别判断某台机器的问题来自轴承、电路和安装误差。在维修之前，把判断、理由和各自掌握的材料记下来；维修之后，查看故障实际出现在哪里，哪些观察起了作用，哪些判断忽略了重要条件。这个结果可以帮助下一次判断，却不能简单推成“猜对的人今后在一切事情上都更有权力”。

如果机器换了型号，原来很有用的经验也许就需要重新校准。如果某个人始终只在最容易的问题上发言，他的高准确率也不能和承担困难问题的人直接比较。所谓动态，就包括这些条件的变化，而不只是把一个分数每天加减一次。''')
c.heading('个人 AI 怎样使广泛参与成为日常能力')
c.src('R34498',start='也有很多人，将自己和别人的总结的经验和技能写进skill文档',end='提交用户主动参与后的意见。',replacements=[('自己和别人的总结的经验','自己和别人总结的经验'),('skill文档','技能文档'),('这个人的机能，认知以及偏好','这个人的技能、认知以及偏好'),('且不会被篡改','让后续修改能够被核验和追踪'),('相当于一种更广泛的知识产权标记','相当于为知识和能力留下更广泛的来源标记'),('当遇到6中提到的团体需要的决策问题时','当遇到团体需要共同判断的问题时'),('AI就能自动根据自身数字空间中的记录，提供自己的意见和看法了','AI 就可以依据这个人的数字空间中的记录，协助形成意见和看法')])
c.src('R34511',2,replacements=[('一方面，我们将','一方面，可以将'),('全人类的数字空间中的所有知识和信息','能够共同使用的知识和信息'),('基于所有人的理论共识，训练出一个全人类共同认可的公共知识的模型底座','把不断形成和修正的理论共识，用于构建共同的公共知识模型底座'),('另一方面，如果我们将每个人的数字空间中的所有内容都通过merkle-DAG架构记录下来','另一方面，如果我们将每个人愿意保留的数字空间内容，通过 Merkle-DAG 架构记录下来'),('对公共知识底座模型的权重，进行基于个人信息，偏好以及认知的个人模型','在公共知识底座之上，形成基于个人信息、偏好以及认知的个人模型'),('这个模型就是代表这个人的个人权益及意见的理性智能','这个模型就可以成为帮助这个人表达个人权益及意见的理性智能'),('简单的，routine的或者trivial的小事情的判断由AI代理自动完成','获得本人授权后，简单、例行的小事情可以由 AI 代理完成判断'),('重大事情，由AI和人类用户共同讨论后提供意见','重大事情，由 AI 和人类用户共同讨论后提供意见'),('所有这些过程也全程通过merkle系统记录下来','这些过程也可以通过 Merkle 系统记录下来')])
c.add('''这使“人人参与”有了与过去不同的含义。过去一说所有人共同决定，人们马上想到每个人要读完成堆文件、参加无数会议、对所有问题投票。对于一个需要工作、学习和照顾家庭的人，这样的参与几乎不可能持续。

个人 AI 可以先理解问题与本人有什么关系，哪些条件属于本人已经明确表达的偏好，哪些部分又出现了新的选择。对于熟悉的例行事务，它可以按照已有授权协助处理；对于真正需要本人选择的事情，它把争议、理由和影响解释清楚，再由本人决定。这样，参与的深度可以因兴趣和问题而不同，而每个人的意见不必因为缺少时间或专业术语就被排除。

同时，一个人也可以改变自己。个人模型记录的是他怎样形成判断，不应该把过去的偏好变成一套永远不能修改的性格判决。本人学习到了新知识，生活条件改变了，或者只是认真思考后有了新的看法，这些变化都应该进入后续的判断。''')
c.heading('反馈为什么比一次性的权威判断更重要')
c.src('R54886',11,replacements=[('其实这也是我想说的：',''),('这个世界进化的方向，是用','我所关注的一条进化方向，是用')])
c.src('R54886',16,19,replacements=[('就像人的副交感神经根本不用通过大脑，就能控制血液循环、呼吸和消化。这种体内的自动运行，不需要大脑参与理智推断，就可以完成很多任务','就像人体内的许多自动调节，并不需要我们每一次都经过有意识的思考，就能够持续进行'),('比如开车过程中遭遇某种情况，如果在理智控制下，可能就会化险为夷；如果由生理肌肉记忆的本能来驱动，有时反倒适得其反，当然有时也会救命，这需要看情况而定','比如开车过程中遭遇某种情况，熟练动作和新的判断需要配合：有时应该立即按已有训练作出反应，有时则需要识别出环境已经变化'),('把大脑的高级神经调节和副交感神经、身体内的本能驱动很好地结合起来解决问题','把有意识的判断、经过训练的熟练动作和身体的自动调节结合起来解决问题'),('选出大家最终达成共识的方案来解决问题，而不是靠市场经济','形成能够共同实施、接受检验和修正的方案，而不把一切都留给未经协调的市场结果')])
c.add('''长期规划与快速纠错，也可以在这个层次上重新理解。一条铁路的建设需要多年协调，不能今天刚确定路线，明天就因为一次情绪变化全部重来。但如果地质条件、运输需求或成本发生了重要变化，继续坚持原方案也可能造成更大的损失。

好的长期承诺，应当包含怎样识别变化、什么情况需要重新评估。共同记忆让我们知道当初为什么作出决定，持续反馈让我们知道这些理由是否还成立。这样，修正计划就可以成为执行计划的一部分，而不必先经历一次最高职位的更替。''')
c.heading('权重会不会重新变成特权')
c.src('R54733',0,replacements=[('关于你提到的动态权重也可能重新中心化的风险，我觉得从物理学机制上来讲不太可能','对于动态权重会不会重新集中成少数人的权力，我的一个判断是，不能忽略能力差异与权力积累之间的区别'),('人类的智商和能力和很多物理性质的分布一样，其实是正态分布的，所有的幂分布都是由于打破平衡的不对等行为经过长时间连锁反应下的产物，比如财富和权力的分布。你觉得呢？','人类能力上的差异，与权力和财富在反复的不对等博弈中所产生的巨大累积，并不是同一种现象')])
c.add('''这条思路所针对的，是一种越赢越能够规定比赛规则的循环。如果过去的成功换来了对资金、信息和准入条件的控制，那么后来的人即使判断更好，也未必能够进入比较。此时所谓“能力优势”已经混入了资源和地位的优势。

所以，动态权重需要与前面所说的公共知识、个人工具和后面要讨论的资源分配放在一起理解。新参与者必须能够获得学习和检验自己判断的条件，失败的记录不能只对弱势者可见，成功者也不能把验证自己结果的通道握在自己手里。

还有一个更直接的问题：如果某人因为过去的判断获得较高权重，他会不会为了维持这个权重而隐瞒错误？这正说明评分也需要面对系统的反馈。及时发现自己的错误、提供反例、帮助修正规则，本来就是有价值的知识贡献。如果记录只奖励“从来没错过”，人们就有理由隐藏失败；如果修正过程也能得到承认，那么改变判断就不必等于失去一切。

谁来修改权重规则，也不能被留给一个永远不接受评价的职位。规则本身要作为共同研究的对象：它使用了什么资料，在什么任务中有效，是否遗漏了重要反馈，换一种规则会发生什么。不同候选机制可以先在可比较的任务中检验，再决定它们适合承担多大的作用。动态权重的含义，必须一直延伸到产生权重的机制本身。''')
c.src('R34496',29,start='我设想的新体制，在政治层面上',replacements=[('管理文明体中所有人的，是所有人作为其中的一个神经元，所形成的文明大脑所产生的智慧知识','共同事务的管理，来自所有人作为参与节点所形成的文明大脑，来自它持续产生和修正的智慧与知识')])
c.add('''不过，让每个人成为共同决策的一部分，还需要回答一个更切身的问题：如果一个人的判断权重下降，他的生活会不会也被削减？如果某个人在专业领域里作出了更大的贡献，他是不是就应该永久拥有更多共同资源？这两个问题把我们带到制度中另一项关键的构造：个人需求和集体资源必须分开讨论。''')
c.polish([('根据每个人对某些领域谁更擅长，', '考察每个人在相应领域中的判断，'), ('我希望它成为一个比资本主义制度更适应新时代智力劳动自动化的新生产力的生产关系架构', '我希望它成为一个比资本主义制度更适应新时代智力劳动自动化的新生产力的生产关系架构。'), ('根据新的反馈动态调整其在该领域意见的权重。这种安排', '根据新的反馈动态调整其在该领域意见的权重。\n\n这种安排'), ('快速自动的提供答案和解决方案，遇到简单的不确定性问题时，', '快速自动地提供答案和解决方案；遇到简单的不确定性问题时，'), ('通过AI智能体的协作来提供答案和解决方案，遇到涉及社会政治经济层面的复杂不确定性问题时，', '通过 AI 智能体的协作来提供答案和解决方案。\n\n遇到涉及社会政治经济层面的复杂不确定性问题时，'), ('而每次的反馈结果，会修改之前各个节点的决策权重值，我希望', '而每次的反馈结果，会修改各个节点的决策权重值。\n\n我希望'), ('并不是同一种现象', '并不是同一种现象。')])
